import re
blocks=[]
cur=None
for line in open('ocr.txt'):
    line=line.rstrip('\n')
    if line.startswith('===='):
        if cur is not None: blocks.append(cur)
        cur=[]
    else:
        cur.append(line.rstrip())
if cur: blocks.append(cur)

def buf(b):
    # drop status bar = first line
    L=b[1:]
    # trailing empties trim
    while L and L[-1]=='' : L.pop()
    return L

def matchscore(a,b):
    # a,b same length lists; return fraction equal (ignoring blanks both)
    if not a: return 0
    eq=0
    for x,y in zip(a,b):
        if x==y: eq+=1
    return eq/len(a)

doc=buf(blocks[0])
for b in blocks[1:]:
    L=buf(b)
    if not L: continue
    best_m=0; best=0
    maxm=min(len(doc),len(L))
    for m in range(maxm,0,-1):
        s=matchscore(doc[-m:],L[:m])
        # prefer large m with high score; last line may differ (typing)
        thresh=0.85 if m>=3 else 1.0
        if s>=thresh:
            best_m=m; break
    if best_m==0:
        # no overlap found; check if L entirely new? or maybe scrolled a lot
        # try smaller: any single-line match near end
        best_m=0
    new=L[best_m:]
    # when best_m>0, the overlapping tail: doc's last lines might be partial (typed);
    # replace overlap with L's version (more complete) then append new
    if best_m>0:
        doc=doc[:-best_m]+L[:best_m]+new
    else:
        doc=doc+L
open('doc.txt','w').write('\n'.join(doc))
cmds=[l for l in doc if l.startswith('>')]
print(len(doc),'lines', len(cmds),'cmds')
for c in cmds[:40]: print(repr(c))
