import re, difflib
blocks=[]; cur=None
for line in open('ocr.txt'):
    line=line.rstrip('\n')
    if line.startswith('===='):
        if cur is not None: blocks.append(cur)
        cur=[]
    else: cur.append(line.rstrip())
if cur: blocks.append(cur)

def norm(x): return re.sub(r'\s+',' ',x).strip().lower()
def buf(b):
    return [x for x in b[1:] if x.strip()!='']

def eq(a,b):
    a,b=norm(a),norm(b)
    if a==b: return True
    if not a or not b: return False
    return difflib.SequenceMatcher(None,a,b).ratio()>0.75

doc=buf(blocks[0])
for b in blocks[1:]:
    L=buf(b)
    if not L: continue
    W=len(L)
    chosen=None
    # try smallest scroll (largest overlap) first
    for s in range(0, min(W,len(doc))+1):
        ov=W-s
        if ov<3: break
        tail=doc[-ov:]
        m=sum(1 for x,y in zip(tail,L[:ov]) if eq(x,y))
        if m/ov>=0.6:
            chosen=(s,ov); break
    if chosen:
        s,ov=chosen
        doc=doc[:-ov]+L  # replace overlap with corrected L, append new
    else:
        doc=doc+L
open('doc.txt','w').write('\n'.join(doc))
cmds=[l for l in doc if l.startswith('>')]
print(len(doc),'lines', len(cmds),'cmds')
